namespace ghidra.feature.vt.gui.actions;



using docking;
using docking.action;
using generic.theme;
using ghidra.feature.vt.gui.editors;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.provider.matchtable;
using ghidra.util;

public class EditAllTagsAction : DockingAction {

	private static readonly string MENU_GROUP = VTPlugin.TAG_MENU_GROUP;
	private static readonly Icon EDIT_TAG_ICON =
		new GIcon("icon.version.tracking.action.edit.all.tags");
	private static readonly string ACTION_NAME = "Edit VTMatch Tags";

	private VTController controller;

	public EditAllTagsAction(VTController controller) : base(ACTION_NAME, VTPlugin.OWNER)
    {
		this.controller = controller;

		setDescription("Edit Match Tags");
		setToolBarData(new ToolBarData(EDIT_TAG_ICON, MENU_GROUP));
		MenuData menuData = new MenuData(new string[] { "Edit Tags" }, EDIT_TAG_ICON, MENU_GROUP);
		menuData.setMenuSubGroup("3"); // after the Remove... action
		setPopupMenuData(menuData);
		setEnabled(false);
		setHelpLocation(new HelpLocation("VersionTrackingPlugin", "Edit_Tag"));

	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		editTag();
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (!(context is VTMatchContext)) {
			return false;
		}

		VTMatchContext matchContext = (VTMatchContext) context;
		return matchContext.getSession() != null;
	}

	private void editTag() {
		TagEditorDialog dialog = new TagEditorDialog(controller.getSession());
		controller.getTool().showDialog(dialog, controller.getParentComponent());
	}

}
